import { json, getToken, parseRepoUrl } from '../util.js';
import { whoami, getRepo, listContents } from '../github.js';

// POST /api/detect  { repoUrl, token? }
// 检测仓库是否可访问、是否包含 Dockerfile。
// - token：可选。用于读取仓库的 GitHub Token（私有仓库需要）。
//   打包（构建）账户可能与仓库所属账户不同，因此单独提供。
// - 未提供 token 时，优先使用登录账户的 token，否则按公共仓库匿名访问。
export async function detect(request) {
  const body = await request.json().catch(() => ({}));
  const { owner, repo } = parseRepoUrl(body.repoUrl);
  const readToken = String(body.token || '').trim() || getToken(request) || null;

  let repoInfo;
  try {
    repoInfo = await getRepo(readToken, owner, repo);
  } catch {
    if (!readToken) {
      return json({
        ok: false,
        message: '仓库不存在或为私有仓库。检测私有仓库请在「检测 Token」处填写可读取该仓库的 GitHub Token；公共仓库无需填写。'
      });
    }
    throw new Error('仓库不存在，或该 Token 无权访问该仓库');
  }

  const branch = repoInfo.default_branch;

  let login = null;
  if (readToken) {
    try {
      login = (await whoami(readToken)).login;
    } catch {
      // 读取 token 无效时忽略，仅影响展示
    }
  }

  let rootItems = [];
  try {
    rootItems = await listContents(readToken, owner, repo, '', branch);
  } catch {
    // 目录读取失败按无处理
  }

  let dockerfile = null;
  const rootFile = rootItems.find((i) => i.type === 'file' && /^Dockerfile/.test(i.name));
  if (rootFile) {
    dockerfile = rootFile.path;
  } else if (rootItems.some((i) => i.type === 'dir' && i.name === 'docker')) {
    try {
      const dockerItems = await listContents(readToken, owner, repo, 'docker', branch);
      const f = dockerItems.find((i) => i.type === 'file' && /^Dockerfile/.test(i.name));
      if (f) dockerfile = f.path;
    } catch {
      // 忽略
    }
  }

  return json({
    ok: !!dockerfile,
    login,
    fullName: repoInfo.full_name,
    owner,
    repo,
    private: repoInfo.private,
    branch,
    htmlUrl: repoInfo.html_url,
    dockerfile,
    message: dockerfile
      ? null
      : '未在仓库根目录或 docker/ 目录找到 Dockerfile（可包含 Dockerfile.* 后缀变体）'
  });
}
