// 注入目标仓库的构建 workflow 模板（路径：.github/workflows/docker-build.yml）。
// 说明：
// - env_vars 以 base64 传入（由 Worker 打包前编码），避免换行/特殊字符破坏 shell 脚本
// - 多架构时自动启用 QEMU 模拟
// - 环境变量通过「ENV 覆盖层」注入：先按原 Dockerfile 构建 :tag-base，再生成
//   FROM base + ENV 行的 Dockerfile.baked 构建最终 :tag，不改动原 Dockerfile
export const WORKFLOW_YAML = `name: docker-build-web

on:
  workflow_dispatch:
    inputs:
      tag:
        description: '镜像 Tag'
        required: true
        default: 'latest'
      platforms:
        description: '构建架构，逗号分隔，如 linux/amd64,linux/arm64'
        required: true
        default: 'linux/amd64'
      env_vars:
        description: '内置环境变量（KEY=VALUE 每行一个，base64 编码）'
        required: false
        default: ''
      docker_user:
        description: 'Docker Hub 用户名'
        required: true

jobs:
  build:
    runs-on: ubuntu-latest
    permissions:
      contents: read
    steps:
      - name: Checkout
        uses: actions/checkout@v4

      - name: Set up QEMU
        if: \$\{{ contains(inputs.platforms, 'linux/arm') || contains(inputs.platforms, 'linux/386') }}
        uses: docker/setup-qemu-action@v3

      - name: Set up Buildx
        uses: docker/setup-buildx-action@v3

      - name: Login to Docker Hub
        uses: docker/login-action@v3
        with:
          username: \$\{{ secrets.DOCKERHUB_USERNAME }}
          password: \$\{{ secrets.DOCKERHUB_TOKEN }}

      - name: Build and push base image
        uses: docker/build-push-action@v6
        with:
          context: .
          platforms: \$\{{ inputs.platforms }}
          push: true
          tags: \$\{{ inputs.docker_user }}/\$\{{ github.event.repository.name }}:\$\{{ inputs.tag }}-base
          labels: |
            org.opencontainers.image.source=https://github.com/\$\{{ github.repository }}
            org.opencontainers.image.revision=\$\{{ github.sha }}

      - name: Generate env overlay Dockerfile
        if: \$\{{ inputs.env_vars != '' }}
        shell: bash
        run: |
          cat > Dockerfile.baked <<'EOF'
          ARG BASE_IMAGE=\$\{{ inputs.docker_user }}/\$\{{ github.event.repository.name }}:\$\{{ inputs.tag }}-base
          FROM \${BASE_IMAGE}
          EOF
          echo "\$\{{ inputs.env_vars }}" | base64 -d 2>/dev/null | while IFS= read -r line; do
            [ -n "$line" ] && echo "ENV $line" >> Dockerfile.baked
          done
          echo "--- Dockerfile.baked ---"
          cat Dockerfile.baked

      - name: Build and push final image
        if: \$\{{ inputs.env_vars != '' }}
        uses: docker/build-push-action@v6
        with:
          context: .
          file: Dockerfile.baked
          platforms: \$\{{ inputs.platforms }}
          push: true
          tags: \$\{{ inputs.docker_user }}/\$\{{ github.event.repository.name }}:\$\{{ inputs.tag }}
          labels: |
            org.opencontainers.image.source=https://github.com/\$\{{ github.repository }}
            org.opencontainers.image.revision=\$\{{ github.sha }}
`;
